// Executable entry point for the Rust translation of c_src/src/main.c.
// The whole program body lives in `imp` so that the `cdylib` target
// (src/lib.rs) can expose the very same code through the C ABI.

mod imp;

fn main() {
    let status = imp::program_main();
    std::process::exit(status);
}
